// 这样从仓库根运行、以及 go test 在包目录 inventory/ 下运行时都能找到同一个文件。
func thresholdsFilePath() string {
	const rel = "inventory/" + thresholdsFileName
	dir, err := os.Getwd()
	if err != nil {
		return rel
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return filepath.Join(dir, "inventory", thresholdsFileName)
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return rel
		}
		dir = parent
	}
}
